191	    /**
192	     * <p>Reverses the order of the given array.</p>
193	     *
194	     * <p>There is no special handling for multi-dimensional arrays.</p>
195	     *
196	     * <p>This method does nothing for a <code>null</code> input array.</p>
197	     *
198	     * @param array the array to reverse, may be <code>null</code>
199	     */
200	    public static <T> void reverse(T[] array) {
201	        if (array == null) {
202	            return;
203	        }
204	        int i = 0;
205	        int j = array.length - 1;
206	        T tmp;
207	        while (j > i) {
208	            tmp = array[j];
209	            array[j] = array[i];
210	            array[i] = tmp;
211	            j--;
212	            i++;
213	        }
214	    }
