470	    @Nullable
471	    private static Object realSubArray(@Nullable Object array, int startIndexInclusive, int endIndexExclusive) {
472	        if (array == null) {
473	            return null;
474	        }
475	        if (startIndexInclusive < 0) {
476	            startIndexInclusive = 0;
477	        }
478	        int length = getLength(array);
479	        if (endIndexExclusive > length) {
480	            endIndexExclusive = length;
481	        }
482	        int newSize = endIndexExclusive - startIndexInclusive;
483	        Class type = array.getClass().getComponentType();
484	        if (newSize <= 0) {
485	            return Array.newInstance(type, 0);
486	        }
487	        Object subArray = Array.newInstance(type, newSize);
488	        System.arraycopy(array, startIndexInclusive, subArray, 0, newSize);
489	        return subArray;
490	    }
