496	    /**
497	     * <p>Copies the given array and adds the given element at the end of the new array.</p>
498	     *
499	     * <p>The new array contains the same elements of the input
500	     * array plus the given element in the last position. The component type of
501	     * the new array is the same as that of the input array.</p>
502	     *
503	     * <p>If the input array is <code>null</code>, a new one element array is returned
504	     * whose component type is the same as the element.</p>
505	     *
506	     * <pre>
507	     * ArrayUtils.realAdd(null, null)      = [null]
508	     * ArrayUtils.realAdd(null, "a")       = ["a"]
509	     * ArrayUtils.realAdd(["a"], null)     = ["a", null]
510	     * ArrayUtils.realAdd(["a"], "b")      = ["a", "b"]
511	     * ArrayUtils.realAdd(["a", "b"], "c") = ["a", "b", "c"]
512	     * </pre>
513	     *
514	     * @param array   the array to "realAdd" the element to, may be <code>null</code>
515	     * @param element the object to realAdd
516	     * @return A new array containing the existing elements plus the new element
517	     */
518	    @NonNull
519	    public static <T> T[] add(@Nullable T[] array, @Nullable T element) {
520	        Class type = array != null ? array.getClass() : (element != null ? element.getClass() : Object.class);
521	        return (T[]) realAddOne(array, element, type);
522	    }
