564	    @NonNull
565	    private static Object realAddOne(@Nullable Object array, @Nullable Object element, Class newArrayComponentType) {
566	        Object newArray;
567	        int arrayLength = 0;
568	        if (array != null) {
569	            arrayLength = getLength(array);
570	            newArray = Array.newInstance(array.getClass().getComponentType(), arrayLength + 1);
571	            System.arraycopy(array, 0, newArray, 0, arrayLength);
572	        } else {
573	            newArray = Array.newInstance(newArrayComponentType, 1);
574	        }
575	        Array.set(newArray, arrayLength, element);
576	        return newArray;
577	    }
