579	    /**
580	     * <p>Adds all the elements of the given arrays into a new array.</p>
581	     * <p>The new array contains all of the element of <code>array1</code> followed
582	     * by all of the elements <code>array2</code>. When an array is returned, it is always
583	     * a new array.</p>
584	     *
585	     * <pre>
586	     * ArrayUtils.add(null, null)     = null
587	     * ArrayUtils.add(array1, null)   = copy of array1
588	     * ArrayUtils.add(null, array2)   = copy of array2
589	     * ArrayUtils.add([], [])         = []
590	     * ArrayUtils.add([null], [null]) = [null, null]
591	     * ArrayUtils.add(["a", "b", "c"], ["1", "2", "3"]) = ["a", "b", "c", "1", "2", "3"]
592	     * </pre>
593	     *
594	     * @param array1 the first array whose elements are added to the new array, may be <code>null</code>
595	     * @param array2 the second array whose elements are added to the new array, may be <code>null</code>
596	     * @return The new array, <code>null</code> if <code>null</code> array inputs.
597	     * The type of the new array is the type of the first array.
598	     */
599	    @Nullable
600	    public static <T> T[] add(@Nullable T[] array1, @Nullable T[] array2) {
601	        return (T[]) realAddArr(array1, array2);
602	    }
