644	    private static Object realAddArr(@Nullable Object array1, @Nullable Object array2) {
645	        if (array1 == null && array2 == null) return null;
646	        if (array1 == null) {
647	            return realCopy(array2);
648	        }
649	        if (array2 == null) {
650	            return realCopy(array1);
651	        }
652	        int len1 = getLength(array1);
653	        int len2 = getLength(array2);
654	        Object joinedArray = Array.newInstance(array1.getClass().getComponentType(), len1 + len2);
655	        System.arraycopy(array1, 0, joinedArray, 0, len1);
656	        System.arraycopy(array2, 0, joinedArray, len1, len2);
657	        return joinedArray;
658	    }
