660	    /**
661	     * <p>Inserts the specified element at the specified position in the array.
662	     * Shifts the element currently at that position (if any) and any subsequent
663	     * elements to the right (adds one to their indices).</p>
664	     *
665	     * <p>This method returns a new array with the same elements of the input
666	     * array plus the given element on the specified position. The component
667	     * type of the returned array is always the same as that of the input
668	     * array.</p>
669	     *
670	     * <p>If the input array is <code>null</code>, a new one element array is returned
671	     * whose component type is the same as the element.</p>
672	     *
673	     * <pre>
674	     * ArrayUtils.add(null, 0, null)        = null
675	     * ArrayUtils.add(null, 0, ["a"])       = ["a"]
676	     * ArrayUtils.add(["a"], 1, null)       = ["a"]
677	     * ArrayUtils.add(["a"], 1, ["b"])      = ["a", "b"]
678	     * ArrayUtils.add(["a", "b"], 2, ["c"]) = ["a", "b", "c"]
679	     * </pre>
680	     *
681	     * @param array1 the array to realAdd the element to, may be <code>null</code>
682	     * @param index  the position of the new object
683	     * @param array2 the array to realAdd
684	     * @return A new array containing the existing elements and the new element
685	     * @throws IndexOutOfBoundsException if the index is out of range
686	     *                                   (index < 0 || index > array.length).
687	     */
688	    @Nullable
689	    public static <T> T[] add(@Nullable T[] array1, int index, @Nullable T[] array2) {
