756	    @Nullable
757	    private static Object realAddArr(@Nullable Object array1, int index, @Nullable Object array2, Class clss) {
758	        if (array1 == null && array2 == null) return null;
759	        int len1 = getLength(array1);
760	        int len2 = getLength(array2);
761	        if (len1 == 0) {
762	            if (index != 0) {
763	                throw new IndexOutOfBoundsException("Index: " + index + ", array1 Length: 0");
764	            }
765	            return realCopy(array2);
766	        }
767	        if (len2 == 0) {
768	            return realCopy(array1);
769	        }
770	        if (index > len1 || index < 0) {
771	            throw new IndexOutOfBoundsException("Index: " + index + ", array1 Length: " + len1);
772	        }
773	        Object joinedArray = Array.newInstance(array1.getClass().getComponentType(), len1 + len2);
774	        if (index == len1) {
775	            System.arraycopy(array1, 0, joinedArray, 0, len1);
776	            System.arraycopy(array2, 0, joinedArray, len1, len2);
777	        } else if (index == 0) {
778	            System.arraycopy(array2, 0, joinedArray, 0, len2);
779	            System.arraycopy(array1, 0, joinedArray, len2, len1);
780	        } else {
781	            System.arraycopy(array1, 0, joinedArray, 0, index);
782	            System.arraycopy(array2, 0, joinedArray, index, len2);
783	            System.arraycopy(array1, index, joinedArray, index + len2, len1 - index);
784	        }
785	        return joinedArray;
786	    }
