788	    /**
789	     * <p>Inserts the specified element at the specified position in the array.
790	     * Shifts the element currently at that position (if any) and any subsequent
791	     * elements to the right (adds one to their indices).</p>
792	     *
793	     * <p>This method returns a new array with the same elements of the input
794	     * array plus the given element on the specified position. The component
795	     * type of the returned array is always the same as that of the input
796	     * array.</p>
797	     *
798	     * <p>If the input array is <code>null</code>, a new one element array is returned
799	     * whose component type is the same as the element.</p>
800	     *
801	     * <pre>
802	     * ArrayUtils.add(null, 0, null)      = [null]
803	     * ArrayUtils.add(null, 0, "a")       = ["a"]
804	     * ArrayUtils.add(["a"], 1, null)     = ["a", null]
805	     * ArrayUtils.add(["a"], 1, "b")      = ["a", "b"]
806	     * ArrayUtils.add(["a", "b"], 3, "c") = ["a", "b", "c"]
807	     * </pre>
808	     *
809	     * @param array   the array to realAdd the element to, may be <code>null</code>
810	     * @param index   the position of the new object
811	     * @param element the object to realAdd
812	     * @return A new array containing the existing elements and the new element
813	     * @throws IndexOutOfBoundsException if the index is out of range
814	     *                                   (index < 0 || index > array.length).
815	     */
816	    @NonNull
817	    public static <T> T[] add(@Nullable T[] array, int index, @Nullable T element) {
818	        Class clss;
819	        if (array != null) {
820	            clss = array.getClass().getComponentType();
821	        } else if (element != null) {
822	            clss = element.getClass();
823	        } else {
824	            return (T[]) new Object[]{null};
825	        }
826	        return (T[]) realAdd(array, index, element, clss);
827	    }
