869	    @NonNull
870	    private static Object realAdd(@Nullable Object array, int index, @Nullable Object element, Class clss) {
871	        if (array == null) {
872	            if (index != 0) {
873	                throw new IndexOutOfBoundsException("Index: " + index + ", Length: 0");
874	            }
875	            Object joinedArray = Array.newInstance(clss, 1);
876	            Array.set(joinedArray, 0, element);
877	            return joinedArray;
878	        }
879	        int length = Array.getLength(array);
880	        if (index > length || index < 0) {
881	            throw new IndexOutOfBoundsException("Index: " + index + ", Length: " + length);
882	        }
883	        Object result = Array.newInstance(clss, length + 1);
884	        System.arraycopy(array, 0, result, 0, index);
885	        Array.set(result, index, element);
886	        if (index < length) {
887	            System.arraycopy(array, index, result, index + 1, length - index);
888	        }
889	        return result;
890	    }
