2040	    /**
2041	     * Executes the given closure on each element in the array.
2042	     * <p>
2043	     * If the input array or closure is null, there is no change made.
2044	     *
2045	     * @param array   The array.
2046	     * @param closure the closure to perform, may be null
2047	     */
2048	    public static <E> void forAllDo(@Nullable Object array, @Nullable Closure<E> closure) {
2049	        if (array == null || closure == null) return;
2050	        if (array instanceof Object[]) {
2051	            Object[] objects = (Object[]) array;
2052	            for (int i = 0, length = objects.length; i < length; i++) {
2053	                Object ele = objects[i];
2054	                closure.execute(i, (E) ele);
2055	            }
2056	        } else if (array instanceof boolean[]) {
2057	            boolean[] booleans = (boolean[]) array;
2058	            for (int i = 0, length = booleans.length; i < length; i++) {
2059	                boolean ele = booleans[i];
2060	                closure.execute(i, (E) (ele ? Boolean.TRUE : Boolean.FALSE));
2061	            }
2062	        } else if (array instanceof byte[]) {
2063	            byte[] bytes = (byte[]) array;
2064	            for (int i = 0, length = bytes.length; i < length; i++) {
2065	                byte ele = bytes[i];
2066	                closure.execute(i, (E) Byte.valueOf(ele));
2067	            }
2068	        } else if (array instanceof char[]) {
2069	            char[] chars = (char[]) array;
2070	            for (int i = 0, length = chars.length; i < length; i++) {
2071	                char ele = chars[i];
2072	                closure.execute(i, (E) Character.valueOf(ele));
2073	            }
2074	        } else if (array instanceof short[]) {
2075	            short[] shorts = (short[]) array;
2076	            for (int i = 0, length = shorts.length; i < length; i++) {
2077	                short ele = shorts[i];
2078	                closure.execute(i, (E) Short.valueOf(ele));
2079	            }
2080	        } else if (array instanceof int[]) {
2081	            int[] ints = (int[]) array;
2082	            for (int i = 0, length = ints.length; i < length; i++) {
2083	                int ele = ints[i];
2084	                closure.execute(i, (E) Integer.valueOf(ele));
2085	            }
2086	        } else if (array instanceof long[]) {
2087	            long[] longs = (long[]) array;
2088	            for (int i = 0, length = longs.length; i < length; i++) {
2089	                long ele = longs[i];
2090	                closure.execute(i, (E) Long.valueOf(ele));
2091	            }
2092	        } else if (array instanceof float[]) {
2093	            float[] floats = (float[]) array;
2094	            for (int i = 0, length = floats.length; i < length; i++) {
2095	                float ele = floats[i];
2096	                closure.execute(i, (E) Float.valueOf(ele));
2097	            }
2098	        } else if (array instanceof double[]) {
2099	            double[] doubles = (double[]) array;
2100	            for (int i = 0, length = doubles.length; i < length; i++) {
2101	                double ele = doubles[i];
2102	                closure.execute(i, (E) Double.valueOf(ele));
2103	            }
2104	        } else {
2105	            throw new IllegalArgumentException("Not an array: " + array.getClass());
2106	        }
2107	    }
2108	
2109	    /**
2110	     * Return the string of array.
2111	     *
2112	     * @param array The array.
2113	     * @return the string of array
2114	     */
2115	    @NonNull
2116	    public static String toString(@Nullable Object array) {
2117	        if (array == null) return "null";
2118	        if (array instanceof Object[]) {
2119	            return Arrays.deepToString((Object[]) array);
2120	        } else if (array instanceof boolean[]) {
2121	            return Arrays.toString((boolean[]) array);
2122	        } else if (array instanceof byte[]) {
2123	            return Arrays.toString((byte[]) array);
2124	        } else if (array instanceof char[]) {
2125	            return Arrays.toString((char[]) array);
2126	        } else if (array instanceof double[]) {
2127	            return Arrays.toString((double[]) array);
2128	        } else if (array instanceof float[]) {
2129	            return Arrays.toString((float[]) array);
2130	        } else if (array instanceof int[]) {
2131	            return Arrays.toString((int[]) array);
2132	        } else if (array instanceof long[]) {
2133	            return Arrays.toString((long[]) array);
2134	        } else if (array instanceof short[]) {
2135	            return Arrays.toString((short[]) array);
2136	        }
2137	        throw new IllegalArgumentException("Array has incompatible type: " + array.getClass());
2138	    }
