926	    /**
927	     * Return the bytes of symmetric encryption or decryption.
928	     *
929	     * @param data           The data.
930	     * @param key            The key.
931	     * @param algorithm      The name of algorithm.
932	     * @param transformation The name of the transformation, e.g., <i>DES/CBC/PKCS5Padding</i>.
933	     * @param isEncrypt      True to encrypt, false otherwise.
934	     * @return the bytes of symmetric encryption or decryption
935	     */
936	    private static byte[] symmetricTemplate(final byte[] data,
937	                                            final byte[] key,
938	                                            final String algorithm,
939	                                            final String transformation,
940	                                            final byte[] iv,
941	                                            final boolean isEncrypt) {
942	        if (data == null || data.length == 0 || key == null || key.length == 0) return null;
943	        try {
944	            SecretKey secretKey;
945	            if ("DES".equals(algorithm)) {
946	                DESKeySpec desKey = new DESKeySpec(key);
947	                SecretKeyFactory keyFactory = SecretKeyFactory.getInstance(algorithm);
948	                secretKey = keyFactory.generateSecret(desKey);
949	            } else {
950	                secretKey = new SecretKeySpec(key, algorithm);
951	            }
952	            Cipher cipher = Cipher.getInstance(transformation);
953	            if (iv == null || iv.length == 0) {
954	                cipher.init(isEncrypt ? Cipher.ENCRYPT_MODE : Cipher.DECRYPT_MODE, secretKey);
955	            } else {
956	                AlgorithmParameterSpec params = new IvParameterSpec(iv);
957	                cipher.init(isEncrypt ? Cipher.ENCRYPT_MODE : Cipher.DECRYPT_MODE, secretKey, params);
958	            }
959	            return cipher.doFinal(data);
960	        } catch (Throwable e) {
961	            e.printStackTrace();
962	            return null;
963	        }
964	    }
