1066	    /**
1067	     * Return the bytes of RSA encryption or decryption.
1068	     *
1069	     * @param data           The data.
1070	     * @param key            The key.
1071	     * @param keySize        The size of key, e.g. 1024, 2048...
1072	     * @param transformation The name of the transformation, e.g., <i>DES/CBC/PKCS1Padding</i>.
1073	     * @param isEncrypt      True to encrypt, false otherwise.
1074	     * @return the bytes of RSA encryption or decryption
1075	     */
1076	    private static byte[] rsaTemplate(final byte[] data,
1077	                                      final byte[] key,
1078	                                      final int keySize,
1079	                                      final String transformation,
1080	                                      final boolean isEncrypt) {
1081	        if (data == null || data.length == 0 || key == null || key.length == 0) {
1082	            return null;
1083	        }
1084	        try {
1085	            Key rsaKey;
1086	            KeyFactory keyFactory;
1087	            if (Build.VERSION.SDK_INT < 28) {
1088	                keyFactory = KeyFactory.getInstance("RSA", "BC");
1089	            } else {
1090	                keyFactory = KeyFactory.getInstance("RSA");
1091	            }
1092	            if (isEncrypt) {
1093	                X509EncodedKeySpec keySpec = new X509EncodedKeySpec(key);
1094	                rsaKey = keyFactory.generatePublic(keySpec);
1095	            } else {
1096	                PKCS8EncodedKeySpec keySpec = new PKCS8EncodedKeySpec(key);
1097	                rsaKey = keyFactory.generatePrivate(keySpec);
1098	            }
1099	            if (rsaKey == null) return null;
1100	            Cipher cipher = Cipher.getInstance(transformation);
1101	            cipher.init(isEncrypt ? Cipher.ENCRYPT_MODE : Cipher.DECRYPT_MODE, rsaKey);
1102	            int len = data.length;
1103	            int maxLen = keySize / 8;
1104	            if (isEncrypt) {
1105	                String lowerTrans = transformation.toLowerCase();
1106	                if (lowerTrans.endsWith("pkcs1padding")) {
1107	                    maxLen -= 11;
1108	                }
1109	            }
1110	            int count = len / maxLen;
1111	            if (count > 0) {
1112	                byte[] ret = new byte[0];
1113	                byte[] buff = new byte[maxLen];
1114	                int index = 0;
1115	                for (int i = 0; i < count; i++) {
1116	                    System.arraycopy(data, index, buff, 0, maxLen);
1117	                    ret = joins(ret, cipher.doFinal(buff));
1118	                    index += maxLen;
1119	                }
1120	                if (index != len) {
1121	                    int restLen = len - index;
1122	                    buff = new byte[restLen];
1123	                    System.arraycopy(data, index, buff, 0, restLen);
1124	                    ret = joins(ret, cipher.doFinal(buff));
1125	                }
1126	                return ret;
1127	            } else {
1128	                return cipher.doFinal(data);
1129	            }
1130	        } catch (Exception e) {
1131	            e.printStackTrace();
1132	        }
1133	        return null;
1134	    }
