1136	    /**
1137	     * Return the bytes of RC4 encryption/decryption.
1138	     *
1139	     * @param data The data.
1140	     * @param key  The key.
1141	     */
1142	    public static byte[] rc4(byte[] data, byte[] key) {
1143	        if (data == null || data.length == 0 || key == null) return null;
1144	        if (key.length < 1 || key.length > 256) {
1145	            throw new IllegalArgumentException("key must be between 1 and 256 bytes");
1146	        }
1147	        final byte[] iS = new byte[256];
1148	        final byte[] iK = new byte[256];
1149	        int keyLen = key.length;
1150	        for (int i = 0; i < 256; i++) {
1151	            iS[i] = (byte) i;
1152	            iK[i] = key[i % keyLen];
1153	        }
1154	        int j = 0;
1155	        byte tmp;
1156	        for (int i = 0; i < 256; i++) {
1157	            j = (j + iS[i] + iK[i]) & 0xFF;
1158	            tmp = iS[j];
1159	            iS[j] = iS[i];
1160	            iS[i] = tmp;
1161	        }
1162	
1163	        final byte[] ret = new byte[data.length];
1164	        int i = 0, k, t;
1165	        for (int counter = 0; counter < data.length; counter++) {
1166	            i = (i + 1) & 0xFF;
1167	            j = (j + iS[i]) & 0xFF;
1168	            tmp = iS[j];
1169	            iS[j] = iS[i];
1170	            iS[i] = tmp;
1171	            t = (iS[i] + iS[j]) & 0xFF;
1172	            k = iS[t];
1173	            ret[counter] = (byte) (data[counter] ^ k);
1174	        }
1175	        return ret;
1176	    }
1177	
1178	    private static byte[] joins(final byte[] prefix, final byte[] suffix) {
1179	        byte[] ret = new byte[prefix.length + suffix.length];
1180	        System.arraycopy(prefix, 0, ret, 0, prefix.length);
1181	        System.arraycopy(suffix, 0, ret, prefix.length, suffix.length);
1182	        return ret;
1183	    }

