 */
public static String int2RgbString(@ColorInt int colorInt) {
    colorInt = colorInt & 0x00ffffff;
    String color = Integer.toHexString(colorInt);
    while (color.length() < 6) {
        color = "0" + color;
    }
    return "#" + color;
}

