 */
public static String int2ArgbString(@ColorInt final int colorInt) {
    String color = Integer.toHexString(colorInt);
    while (color.length() < 6) {
        color = "0" + color;
    }
    while (color.length() < 8) {
        color = "f" + color;
    }
    return "#" + color;
}

