public static String int2ArgbString(@ColorInt final int colorInt) {
    String hex = Integer.toHexString(colorInt);
    int len = hex.length();
    if (len >= 8) return "#" + hex;
    // Pad with leading zeros to 6 digits, then leading 'f's to 8 (alpha=ff means opaque)
    int fPads = Math.max(0, 8 - Math.max(len, 6));
    int zeroPads = Math.max(0, 6 - len);
    StringBuilder sb = new StringBuilder(8);
    for (int i = 0; i < fPads; i++) sb.append('f');
    for (int i = 0; i < zeroPads; i++) sb.append('0');
    return "#" + sb.append(hex);
}

