        Class clss;
        if (array1 != null) {
            clss = array1.getClass().getComponentType();
        } else if (array2 != null) {
            clss = array2.getClass().getComponentType();
        } else {
            return null;
        }
        return (T[]) realAddArr(array1, index, array2, clss);
    }

